export const fontFamily = {
    dinOT: { web: "DIN OT", native: "DINOT-Medium" },
    advercase: { web: "Advercase", native: "Advercase-Regular" },
    ibmPlexMono: { web: "IBM Plex Mono", native: "IBMPlexMono-Regular" },
    sfPro: { web: "SF Pro", native: "SFPro" },
    sfMono: { web: "SF Mono, Courier New, monospace", native: "SFMono" },
};
export const fontSize = {
    xxs: 10,
    xs: 12,
    sm: 14,
    base: 15,
    md: 16,
    ml: 18,
    lg: 20,
    xl: 24,
    xxl: 32,
};
export const fontWeight = {
    regular: "400",
    medium: "500",
    semibold: "600",
    bold: "700",
};
export const lineHeight = {
    tight: 1.2,
    normal: 1.5,
    relaxed: 1.75,
};
export function resolveTypography(platform) {
    const resolved = {};
    for (const [key, value] of Object.entries(fontFamily)) {
        resolved[key] = value[platform];
    }
    return {
        fontFamily: resolved,
        fontSize,
        fontWeight,
        lineHeight,
    };
}
